# A position byte with no event after it (the data of this ROM needs none).
.macro at tick
	.byte \tick
.endm
# The beat marker (a stream holds bars x beats of them) and the end of the stream.
.macro beat
	.byte 0xf4
.endm
.macro end
	.byte 0xf5
.endm
