# ---- the header (StyleBuiltinNameTableInit, StyleResourceVerify) -----------------
.org 0x10000
TechnicsRhythms:
	.ascii	"Technics Rhythms"		# strncmp with the firmware's 0x4872980C
	.be16	0xe2da			# SumU16BE of the halfwords below, StyleResourceVerify
	.be24	0x100000			# checksum start, from TechnicsRhythms: file 0x110000, inside a stream
	.be24	0x100000			# checksum length in halfwords (2 MB)
	.be24	RhythmCountBlock - TechnicsRhythms
	.be24	RhythmStyleIndex - TechnicsRhythms	# -> 0x50034B7C
	.be24	RhythmStyleTable - TechnicsRhythms	# -> 0x50034B80
	.be24	RhythmCountInTable - TechnicsRhythms	# -> 0x50034B84
	.be24	Style_8BtStandard - TechnicsRhythms	# -> 0x50034B88, the fallback style
RhythmCountBlock:
# Only the u16 at +2 is read (StyleBuiltinNameTableInit: `add 2, a0` / LoadU16BE); no routine
# reads the other ten bytes (notes/mn10300-names-probes/rhythm_count_block_readers.py).
	.be16	0			# unread
	.be16	220			# the rhythm count -> 0x50034B74; the index's limit
	.be16	96			# unread; [INFERENCE] ticks a beat: every position byte of every stream is 0..95
	.byte	13, 8, 4, 2, 2, 2	# unread; [INFERENCE] name length 13, 8 parts, 4 variations, 2 fill-ins,
					# 2 intros, 2 endings (4 + 4x2 + 2x2 + 2x2 = 20 slots)

